class Solution {
    public int[] topGenres(int[] plays, int k) {
        boolean[] left = new boolean[20001];
        for (int g : plays) left[g + 10000] = true;
        int[] out = new int[k];
        for (int r = 0; r < k; r++) {
            int best = -1, bestCount = 0;
            for (int i = 0; i < 20001; i++) {
                if (!left[i]) continue;
                int c = 0;
                for (int g : plays) if (g == i - 10000) c++;
                if (c > bestCount) { best = i; bestCount = c; }
            }
            out[r] = best - 10000;
            left[best] = false;
        }
        return out;
    }
}

