class Solution {
    public int[] topGenres(int[] plays, int k) {
        int[] count = new int[20001];
        for (int g : plays) count[g + 10000]++;
        List<Integer> genres = new ArrayList<>();
        for (int i = 0; i < 20001; i++) if (count[i] > 0) genres.add(i - 10000);
        genres.sort((a, b) -> count[a + 10000] != count[b + 10000]
                ? count[b + 10000] - count[a + 10000] : a - b);
        int[] out = new int[k];
        for (int i = 0; i < k; i++) out[i] = genres.get(i);
        return out;
    }
}

