public:
    vector<int> topGenres(vector<int>& plays, int k) {
        vector<int> count(20001, 0);
        for (int g : plays) count[g + 10000]++;
        vector<int> genres;
        for (int i = 0; i < 20001; i++) if (count[i]) genres.push_back(i - 10000);
        sort(genres.begin(), genres.end(), [&](int a, int b) {
            int ca = count[a + 10000], cb = count[b + 10000];
            return ca != cb ? ca > cb : a < b;
        });
        return vector<int>(genres.begin(), genres.begin() + k);
    }
};

