import heapq

class Solution:
    def topGenres(self, plays: List[int], k: int) -> List[int]:
        count = [0] * 20001
        for g in plays:
            count[g + 10000] += 1
        heap = []
        for i in range(20001):
            if not count[i]:
                continue
            item = (count[i], -(i - 10000))
            if len(heap) < k:
                heapq.heappush(heap, item)
            elif item > heap[0]:
                heapq.heapreplace(heap, item)
        best = sorted(heap, reverse=True)
        return [-g for _, g in best]

