typedef struct { int plays, id; } Entry;

// a is weaker than b: fewer plays, or as many plays and a larger id.
static bool weaker(Entry a, Entry b) {
    return a.plays != b.plays ? a.plays < b.plays : a.id > b.id;
}

static void siftDown(Entry* h, int size, int i) {
    while (true) {
        int l = 2 * i + 1, r = l + 1, w = i;
        if (l < size && weaker(h[l], h[w])) w = l;
        if (r < size && weaker(h[r], h[w])) w = r;
        if (w == i) return;
        Entry t = h[i]; h[i] = h[w]; h[w] = t;
        i = w;
    }
}

static void siftUp(Entry* h, int i) {
    while (i > 0 && weaker(h[i], h[(i - 1) / 2])) {
        Entry t = h[i]; h[i] = h[(i - 1) / 2]; h[(i - 1) / 2] = t;
        i = (i - 1) / 2;
    }
}

int* topGenres(int* plays, int playsSize, int k, int* returnSize) {
    int* count = calloc(20001, sizeof(int));
    for (int i = 0; i < playsSize; i++) count[plays[i] + 10000]++;
    Entry* heap = malloc(k * sizeof(Entry));
    int size = 0;
    for (int i = 0; i < 20001; i++) {
        if (!count[i]) continue;
        Entry e = {count[i], i - 10000};
        if (size < k) {
            heap[size] = e;
            siftUp(heap, size++);
        } else if (weaker(heap[0], e)) {
            heap[0] = e;
            siftDown(heap, size, 0);
        }
    }
    int* out = malloc(k * sizeof(int));
    for (int i = k - 1; i >= 0; i--) {
        out[i] = heap[0].id;
        heap[0] = heap[--size];
        siftDown(heap, size, 0);
    }
    free(count);
    free(heap);
    *returnSize = k;
    return out;
}

