class Solution:
    def topGenres(self, plays: List[int], k: int) -> List[int]:
        count = [0] * 20001
        for g in plays:
            count[g + 10000] += 1
        bucket = [[] for _ in range(len(plays) + 1)]
        for i in range(20001):
            if count[i]:
                bucket[count[i]].append(i - 10000)
        out = []
        for c in range(len(plays), 0, -1):
            for g in bucket[c]:
                if len(out) == k:
                    return out
                out.append(g)
        return out

