class Solution {
    public int[] topGenres(int[] plays, int k) {
        int n = plays.length;
        int[] count = new int[20001];
        for (int g : plays) count[g + 10000]++;
        List<List<Integer>> bucket = new ArrayList<>();
        for (int c = 0; c <= n; c++) bucket.add(new ArrayList<>());
        for (int i = 0; i < 20001; i++) if (count[i] > 0) bucket.get(count[i]).add(i - 10000);
        int[] out = new int[k];
        int taken = 0;
        for (int c = n; c >= 1 && taken < k; c--)
            for (int g : bucket.get(c))
                if (taken < k) out[taken++] = g;
        return out;
    }
}

