int* topGenres(int* plays, int playsSize, int k, int* returnSize) {
    int n = playsSize;
    int* count = calloc(20001, sizeof(int));
    for (int i = 0; i < n; i++) count[plays[i] + 10000]++;
    int* head = malloc((n + 1) * sizeof(int));
    int* next = malloc(20001 * sizeof(int));
    for (int c = 0; c <= n; c++) head[c] = -1;
    for (int i = 20000; i >= 0; i--) {
        if (!count[i]) continue;
        next[i] = head[count[i]];
        head[count[i]] = i;
    }
    int* out = malloc(k * sizeof(int));
    int taken = 0;
    for (int c = n; c >= 1 && taken < k; c--)
        for (int i = head[c]; i != -1 && taken < k; i = next[i])
            out[taken++] = i - 10000;
    free(count);
    free(head);
    free(next);
    *returnSize = k;
    return out;
}
